cd /exercise && cat > house.js <<'EOF'
//
// This is the House exercise, implemented from the rhyme's recursive
// "that <action> the <subject>" structure.
//

const RHYME = [
  { subject: 'house that Jack built', action: null },
  { subject: 'malt', action: 'lay in' },
  { subject: 'rat', action: 'ate' },
  { subject: 'cat', action: 'killed' },
  { subject: 'dog', action: 'worried' },
  { subject: 'cow with the crumpled horn', action: 'tossed' },
  { subject: 'maiden all forlorn', action: 'milked' },
  { subject: 'man all tattered and torn', action: 'kissed' },
  { subject: 'priest all shaven and shorn', action: 'married' },
  { subject: 'rooster that crowed in the morn', action: 'woke' },
  { subject: 'farmer sowing his corn', action: 'kept' },
  { subject: 'horse and the hound and the horn', action: 'belonged to' },
];

export class House {
  static verse(number) {
    if (!Number.isInteger(number) || number < 1 || number > RHYME.length) {
      throw new RangeError(`Verse must be between 1 and ${RHYME.length}`);
    }

    const lines = [`This is the ${RHYME[number - 1].subject}`];
    for (let i = number - 1; i> 0; i -= 1) {
      lines.push(`that ${RHYME[i].action} the ${RHYME[i - 1].subject}`);
    }

    lines[lines.length - 1] += '.';
    return lines;
  }

  static verses(startVerse, endVerse = startVerse) {
    const verses = [];
    for (let i = startVerse; i <= endVerse; i += 1) {
      if (i > startVerse) {
        verses.push('');
      }
      verses.push(...House.verse(i));
    }
    return verses;
  }
}
